\set ON_ERROR_STOP on
BEGIN;
CREATE TEMP TABLE flashcard_checks(label text);
GRANT INSERT ON flashcard_checks TO authenticated,anon;
CREATE FUNCTION pg_temp.flashcard_assert(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'FAIL: %',label;END IF;INSERT INTO pg_temp.flashcard_checks VALUES(label);END;$$;
CREATE FUNCTION pg_temp.flashcard_denied(statement text,code text,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN IF SQLSTATE=code THEN PERFORM pg_temp.flashcard_assert(true,label);RETURN;END IF;RAISE EXCEPTION 'Unexpected % (%): %',SQLSTATE,label,SQLERRM;END;RAISE EXCEPTION 'Unexpected acceptance: %',label;END;$$;
INSERT INTO auth.users(id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
SELECT id,'authenticated','authenticated',id::text||'@local.invalid','',now(),'{"provider":"email","providers":["email"]}','{"first_name":"LOCAL FLASHCARD FIXTURE","birth_date":"2000-01-01"}',now(),now() FROM unnest(ARRAY['a5800000-0000-4000-8000-000000000001'::uuid,'a5800000-0000-4000-8000-000000000002'::uuid]) id;
UPDATE public.profiles SET role='admin' WHERE id='a5800000-0000-4000-8000-000000000001';
INSERT INTO public.chapters(id,name,order_index,aliases) VALUES('a5810000-0000-4000-8000-000000000001','LOCAL FLASHCARD CHAPTER',998,ARRAY['LOCAL FLASHCARD ALIAS']),('a5810000-0000-4000-8000-000000000002','LOCAL OTHER FLASHCARD CHAPTER',999,'{}');
INSERT INTO public.flashcards(id,chapter,question,answer) VALUES('a5820000-0000-4000-8000-000000000001','LOCAL FLASHCARD ALIAS','Historical alias fixture','Alias answer'),('a5820000-0000-4000-8000-000000000002','UNRESOLVED LEGACY CHAPTER','Legacy raw fixture','Legacy answer');
DO $tests$
DECLARE item jsonb; changed jsonb; current_chapter jsonb; body jsonb:=jsonb_build_object('chapterId','a5810000-0000-4000-8000-000000000001','question','Quelle règle pour $x^2$ ? %_','answer',E'  $2x$\nJustification  '); original_fp text; created text; total_events bigint;
BEGIN
 PERFORM set_config('request.jwt.claim.sub','a5800000-0000-4000-8000-000000000002',true);
 PERFORM set_config('request.jwt.claims','{"sub":"a5800000-0000-4000-8000-000000000002","is_anonymous":false,"role":"admin"}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_list_flashcards()','42501','student and forged role claim cannot list admin flashcards');
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,''{}'')','42501','student cannot mutate flashcards');
 SET LOCAL ROLE anon;
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_list_flashcards()','42501','anon cannot execute admin RPC');
 RESET ROLE;
 PERFORM set_config('request.jwt.claim.sub','a5800000-0000-4000-8000-000000000001',true);
 PERFORM set_config('request.jwt.claims','{"sub":"a5800000-0000-4000-8000-000000000001","is_anonymous":true}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_list_flashcards()','42501','anonymous admin refused');
 RESET ROLE;
 PERFORM set_config('request.jwt.claims','{"sub":"a5800000-0000-4000-8000-000000000001","is_anonymous":false}',true);
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.flashcard_assert((public.admin_list_flashcards()->>'total')::bigint>=2,'admin can list original fixture rows');
 item:=public.admin_mutate_flashcard('save',NULL,NULL,body)->'item';
 PERFORM pg_temp.flashcard_assert(item->>'question'=body->>'question' AND item->>'answer'=body->>'answer','strings whitespace and LaTeX preserved exactly');
 PERFORM pg_temp.flashcard_assert(item->>'chapter'='LOCAL FLASHCARD CHAPTER' AND item->>'chapterId'=body->>'chapterId','stable selector maps to reader-compatible chapter name');
 PERFORM pg_temp.flashcard_assert((item->>'id')::uuid IS NOT NULL AND item->>'createdAt' IS NOT NULL,'server allocates UUID and creation time');
 current_chapter:=public.admin_list_taxonomy('chapter','LOCAL FLASHCARD CHAPTER')->'items'->0;
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_taxonomy(''chapter'',''save'',%L,%L,%L)',current_chapter->>'id',current_chapter->>'fingerprint',((current_chapter->'value')-'id')||'{"name":"RENAMED CHAPTER"}'),'23503','chapter rename cannot hide cards from current exact-name learner');
 PERFORM pg_temp.flashcard_denied('INSERT INTO public.flashcards(chapter,question,answer) VALUES(''X'',''X'',''X'')','42501','direct API insert denied');
 PERFORM pg_temp.flashcard_denied(format('UPDATE public.flashcards SET question=''FORGED'' WHERE id=%L',item->>'id'),'42501','direct API update denied');
 PERFORM pg_temp.flashcard_denied(format('DELETE FROM public.flashcards WHERE id=%L',item->>'id'),'42501','direct API delete denied');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',body||'{"question":"   "}'),'22023','blank question refused in SQL');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',jsonb_set(body,'{answer}',to_jsonb(repeat('x',4001)))),'22023','oversized answer refused in SQL');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',body||'{"created_at":"2000-01-01"}'),'22023','forged timestamp and unknown keys refused');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',body||'{"question":42}'),'22023','non-string question refused');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',body||'{"chapterId":"a5890000-0000-4000-8000-000000000000"}'),'23503','missing chapter refused');
 PERFORM pg_temp.flashcard_assert((public.admin_list_flashcards('%_')->>'total')::bigint=1,'search is literal rather than SQL wildcard');
 PERFORM pg_temp.flashcard_assert((public.admin_list_flashcards('justification')->>'total')::bigint=1,'answer search works');
 PERFORM pg_temp.flashcard_assert((public.admin_list_flashcards('','a5810000-0000-4000-8000-000000000001')->>'total')::bigint=2,'chapter filter includes historical aliases');
 PERFORM pg_temp.flashcard_assert((public.admin_list_flashcards('Historical alias fixture')->'items'->0->>'chapterId')='a5810000-0000-4000-8000-000000000001','old alias resolves without rewriting the stored row');
 PERFORM pg_temp.flashcard_assert(public.admin_list_flashcards('Legacy raw fixture')->'items'->0->>'chapterId' IS NULL,'unresolved reference stays explicit');
 original_fp:=item->>'fingerprint';created:=item->>'createdAt';
 changed:=public.admin_mutate_flashcard('save',(item->>'id')::uuid,original_fp,body||'{"question":"Changed face"}')->'item';
 item:=public.admin_mutate_flashcard('save',(item->>'id')::uuid,changed->>'fingerprint',body)->'item';
 PERFORM pg_temp.flashcard_assert(item->>'createdAt'=created AND item->>'fingerprint'<>original_fp,'creation time stable and epoch detects edit then revert');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',%L,%L,%L)',item->>'id',original_fp,body),'40001','stale update refused after revert');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''delete'',%L,%L,NULL)',item->>'id',original_fp),'40001','stale delete refused');
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_mutate_flashcard(''delete'',NULL,NULL,NULL)','22023','deletion requires explicit identity');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''delete'',%L,%L,%L)',item->>'id',item->>'fingerprint',body),'22023','delete cannot carry replacement content');
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',''a5830000-0000-4000-8000-000000000000'',%L,%L)',repeat('a',64),body),'P0002','unknown UUID is not silently created');
 SELECT count(*) INTO total_events FROM public.admin_flashcard_events;
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',%L,%L,%L)',item->>'id',original_fp,body),'40001','failed mutation produces a conflict');
 PERFORM pg_temp.flashcard_assert((SELECT count(*)=total_events FROM public.admin_flashcard_events),'failed mutation adds no audit event');
 PERFORM pg_temp.flashcard_denied('INSERT INTO public.admin_flashcard_events(actor_id,flashcard_id,action) VALUES(''a5800000-0000-4000-8000-000000000001'',''a5830000-0000-4000-8000-000000000000'',''created'')','42501','audit cannot be forged by API caller');
 PERFORM pg_temp.flashcard_assert(NOT EXISTS(SELECT 1 FROM public.admin_flashcard_events WHERE actor_id<>'a5800000-0000-4000-8000-000000000001'),'all mutation actors come from checked Auth');
 PERFORM pg_temp.flashcard_assert(public.admin_mutate_flashcard('delete',(item->>'id')::uuid,item->>'fingerprint',NULL)->>'action'='deleted','only newly created synthetic card is deleted');
 PERFORM pg_temp.flashcard_assert(EXISTS(SELECT 1 FROM public.admin_flashcard_events WHERE flashcard_id=(item->>'id')::uuid AND action='deleted' AND before_value->>'answer'=body->>'answer' AND after_value IS NULL),'delete audit retains prior content after row removal');
 PERFORM pg_temp.flashcard_assert((SELECT count(*)=4 FROM public.admin_flashcard_events WHERE flashcard_id=(item->>'id')::uuid),'create two updates and deletion each have one event');
 RESET ROLE;
 UPDATE public.chapters SET aliases=ARRAY['LOCAL FLASHCARD CHAPTER'] WHERE id='a5810000-0000-4000-8000-000000000002';
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.flashcard_denied(format('SELECT public.admin_mutate_flashcard(''save'',NULL,NULL,%L)',body),'23505','ambiguous chapter mapping refused');
 RESET ROLE;
 UPDATE public.profiles SET role='user' WHERE id='a5800000-0000-4000-8000-000000000001';
 SET LOCAL ROLE authenticated;
 PERFORM pg_temp.flashcard_denied('SELECT public.admin_list_flashcards()','42501','role revocation takes effect immediately');
 PERFORM pg_temp.flashcard_assert((SELECT count(*)=0 FROM public.admin_flashcard_events),'revoked admin no longer reads audit');
 RESET ROLE;
END;$tests$;
SELECT jsonb_build_object('result','PASS','flashcardsAssertions',count(*)) FROM pg_temp.flashcard_checks;
ROLLBACK;
